1	// Shared game-server order core — the ONE audited debit path for game servers,
2	// used by the wallet flow (lib/actions-gameplans.ts payAndDeployGame /
3	// orderGameServer) AND the Stripe confirm/webhook fulfilment (lib/fulfil-checkout.ts)
4	// so a card-paid game order provisions through the SAME machinery a VPS order does.
5	// Plain server module (NOT "use server") — no secrets, callable from actions,
6	// server components and the worker/webhook alike.
7	//
8	// This is the game analogue of lib/order.ts (orderQuote / placeOrder). It was
9	// factored OUT of the original `orderGameServer` so the card path and the wallet
10	// path settle through one function instead of two copies that could drift.
11	//
12	// MONEY RULES (audited):
13	//   - Prices are strictly DB-fed: `gamePlan.priceCents` is the ONLY source, priced
14	//     through the SAME `termPriceCents` formula the deploy wizard shows and the
15	//     renewal sweep bills (displayed === charged === renewed).
16	//   - Game bills FULL from month 1. There is NO first-month-free on game (that promo
17	//     is Shared-Web-Hosting-only); no $0 path, no coupon, no VAT change here.
18	//   - The wallet is the single debit; `debitWallet` refuses to overdraw.
19	//   - `sold` (card path) carries the price the order was SOLD at, stamped BEFORE the
20	//     card cleared, so fulfilment never re-prices after the money moved (the H2
21	//     incident guarded on lib/order.ts OrderPrice).
22	import { Prisma } from "@prisma/client";
23	import type { User } from "@prisma/client";
24	import { db } from "./db";
25	import { debitWallet, InsufficientBalanceError } from "./wallet";
26	import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
27	import { annualDiscountPct } from "./annual-discount";
28	import { capacityCheck } from "./capacity";
29	import { scheduleNode } from "./node-capacity";
30	import { GAME_FAMILIES, type GameFamily } from "./games";
31	import { schemaFor, isValidVariant, validateConfig } from "./game-config";
32	import { recordDeployFunnelComplete } from "./deploy-funnel";
33	import { getSettingBool, getSettingInt } from "./settings";
34	import { invoiceCreateData, invoiceBranding, formatInvoiceNumber } from "./invoices";
35	
36	export class GameOrderError extends Error {}
37	
38	/**
39	 * Feature + capacity gate shared by every game order entry point: the game-servers
40	 * feature can be switched off platform-wide (flag), and game servers are Server rows
41	 * too so they count toward the per-user cap. Returns a customer-facing error to
42	 * surface, or null to proceed.
43	 *
44	 * Lives in this PLAIN module (not lib/actions-gameplans.ts, which is `"use
45	 * server"`) rather than being exported from there, even though it is only ever
46	 * called with an already-authenticated `user` — a function that takes an
47	 * arbitrary `User`-shaped argument and does no session check of its own is
48	 * exactly what test/auth-lockouts.test.ts's "HAZARD" suite exists to catch the
49	 * moment it is exported from a Server Actions file: every export of such a file
50	 * is a public network endpoint, and this one would let a stranger probe any
51	 * userId's server count with no authentication at all. `lib/actions-gameplans.ts`
52	 * (payAndDeployGame, orderGameServer) and lib/actions-payment-providers.ts
53	 * (PayPal/Coinbase game-order creation) both call this AFTER their own
54	 * `requireUser()` — the guard the network-facing wrapper is responsible for.
55	 */
56	export async function gameOrderGate(user: User): Promise<string | null> {
57	  if (!(await getSettingBool("feature_game_servers", true))) {
58	    return "Game servers aren't available right now.";
59	  }
60	  const cap = await getSettingInt("max_servers_per_user", 10);
61	  if (cap > 0) {
62	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
63	    if (owned >= cap) {
64	      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
65	    }
66	  }
67	  return null;
68	}
69	
70	/** Extract a GameOrderIntent from a deploy form — shared by the wallet/card wizard
71	 *  action (lib/actions-gameplans.ts) and the PayPal/Coinbase order-creation actions
72	 *  (lib/actions-payment-providers.ts), so both parse the SAME form shape. Pure —
73	 *  lives in this plain module for the same "don't export a non-guarding helper from
74	 *  a Server Actions file" reason `gameOrderGate` above documents. */
75	export function gameIntentFromFormData(formData: FormData): GameOrderIntent {
76	  let config: Record<string, unknown> | null = null;
77	  const rawConfig = formData.get("config");
78	  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
79	    try {
80	      const parsed = JSON.parse(rawConfig);
81	      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
82	    } catch {
83	      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
84	      // fills defaults. It can never widen the charge (game is a flat term price).
85	      config = null;
86	    }
87	  }
88	  return {
89	    gamePlanId: String(formData.get("gamePlanId") ?? ""),
90	    termMonths: Number(formData.get("termMonths") ?? 1),
91	    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
92	    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
93	    variant: String(formData.get("variant") ?? "").trim() || undefined,
94	    config,
95	  };
96	}
97	
98	/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
99	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
100	
101	/** Short random suffix so auto-generated hostnames don't collide. */
102	export function randSuffix(n = 6): string {
103	  return Math.random().toString(36).slice(2, 2 + n);
104	}
105	
106	/**
107	 * The customer's full game-order intent — the tier, the billing term and the
108	 * per-game setup captured by the wizard. `config` holds the raw gameplay values
109	 * (validated against the family schema in `gameOrderQuote`); `variant` is the
110	 * server type/loader.
111	 */
112	export type GameOrderIntent = {
113	  gamePlanId: string;
114	  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
115	  termMonths: number;
116	  /** Optional customer-facing nickname → Server.label. */
117	  serverName?: string;
118	  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
119	  hostname?: string;
120	  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
121	  variant?: string;
122	  /** Raw gameplay settings; validated + coerced against the family schema. */
123	  config?: Record<string, unknown> | null;
124	};
125	
126	/**
127	 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
128	 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
129	 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
130	 * OrderPrice, which must also carry promo + VAT).
131	 */
132	export type GameOrderPrice = { chargeCents: number };
133	
134	/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
135	export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
136	  let obj: unknown = raw;
137	  if (typeof raw === "string") {
138	    try {
139	      obj = JSON.parse(raw);
140	    } catch {
141	      return null;
142	    }
143	  }
144	  if (!obj || typeof obj !== "object") return null;
145	  const { chargeCents } = obj as Record<string, unknown>;
146	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
147	  return { chargeCents };
148	}
149	
150	export type GameOrderQuote = {
151	  gamePlanId: string;
152	  gameFamily: string;
153	  planName: string;
154	  basePlanId: string;
155	  /** The base plan's RAM — fed to scheduleNode() to pick a node, same as VPS orders. */
156	  ramMB: number;
157	  osTemplateId: string;
158	  /** Normalised term (1 or 12). */
159	  term: number;
160	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
161	  annualPct: number;
162	  /** DB-fed per-month base (priceCents / termMonths). */
163	  monthlyCents: number;
164	  /** The net charge for the whole term — displayed === charged === renewed. */
165	  chargeCents: number;
166	  hostname: string;
167	  label: string | null;
168	  variant: string;
169	  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
170	  values: Record<string, string | number | boolean>;
171	};
172	
173	/**
174	 * Validate + price a game order without placing it. Throws GameOrderError on any
175	 * problem. Pure of side effects beyond reads. The price is the whole truth about
176	 * what this order costs; the caller (wallet split, review step, checkout stamp)
177	 * quotes from THIS so what the customer sees is what settles.
178	 */
179	export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
180	  const term = normalizeProductTerm(intent.termMonths);
181	
182	  const gp = await db.gamePlan.findUnique({
183	    where: { id: intent.gamePlanId },
184	    include: { basePlan: true },
185	  });
186	  if (!gp || !gp.active) throw new GameOrderError("That game plan isn't available.");
187	  if (!gp.basePlan?.active) throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
188	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
189	    throw new GameOrderError("Unknown game family.");
190	  }
191	
192	  // Resolve the game image: the tier's own OsTemplate, else any active image for
193	  // this family. A game server can't provision without an image.
194	  let osTemplateId = gp.osTemplateId;
195	  if (osTemplateId) {
196	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
197	    if (!os?.active) osTemplateId = null;
198	  }
199	  if (!osTemplateId) {
200	    const os = await db.osTemplate.findFirst({
201	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
202	      orderBy: { sortOrder: "asc" },
203	    });
204	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
205	    osTemplateId = os.id;
206	  }
207	
208	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
209	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
210	  let hostname = rawHost;
211	  if (hostname === "") {
212	    hostname = `${gp.gameFamily}-${randSuffix()}`;
213	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
214	    throw new GameOrderError(
215	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
216	    );
217	  }
218	
219	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
220	
221	  // Per-game setup: variant + gameplay settings, validated against the family
222	  // schema. Families without a customization schema (e.g. Terraria) carry no
223	  // variant and no gameplay values — the wizard shows only identity fields for them.
224	  const schema = schemaFor(gp.gameFamily);
225	  let variant = "";
226	  let values: Record<string, string | number | boolean> = {};
227	  if (schema) {
228	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
229	    if (!isValidVariant(gp.gameFamily, variant)) {
230	      throw new GameOrderError("Choose a valid server type for this game.");
231	    }
232	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
233	    if (!res.ok) throw new GameOrderError(res.error);
234	    values = res.values;
235	  }
236	
237	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
238	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
239	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
240	  const annualPct = await annualDiscountPct();
241	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
242	  const chargeCents = termPriceCents(monthlyCents, term, annualPct);
243	
244	  return {
245	    gamePlanId: gp.id,
246	    gameFamily: gp.gameFamily,
247	    planName: gp.name,
248	    basePlanId: gp.basePlanId,
249	    ramMB: gp.basePlan.ramMB,
250	    osTemplateId,
251	    term,
252	    annualPct,
253	    monthlyCents,
254	    chargeCents,
255	    hostname,
256	    label,
257	    variant,
258	    values,
259	  };
260	}
261	
262	/**
263	 * Place a game order: re-validate + price, capacity-check, then atomically debit
264	 * the wallet and create the Server (sized by the tier's base VPS plan, running the
265	 * game image, with the customer's variant + gameplay settings) plus a PROVISION
266	 * job. Returns the new server id. Does NOT redirect.
267	 *
268	 * `sold` (card path) overrides the recomputed price with the one the order was
269	 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
270	 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
271	 * the customer consented to instead of re-pricing against a rate that changed in
272	 * between. The wallet path omits it and pays the fresh quote it computed moments
273	 * ago. This mirrors `sold` in lib/order.ts placeOrder.
274	 *
275	 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
276	 * path is gated by the balance check in the action). This still enforces the
277	 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
278	 */
279	export async function placeGameOrder(
280	  user: User,
281	  intent: GameOrderIntent,
282	  sold?: GameOrderPrice | null,
283	): Promise<string> {
284	  const quote = await gameOrderQuote(intent);
285	
286	  // Bill off the SOLD price when present (never re-priced after the card cleared),
287	  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
288	  // truth about what this order costs.
289	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
290	
291	  // Oversell guard — the VPS order path enforces this; game orders must too, or a
292	  // game server could commit host RAM past capacity.
293	  const capacity = await capacityCheck(quote.basePlanId);
294	  if (!capacity.ok) {
295	    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
296	  }
297	
298	  // Pick a node the same way a VPS order does — without this, every game
299	  // server's `nodeId` stays null and `worker/index.ts`'s `nodeFor()` fallback
300	  // (`server.node ?? primary node`) pins EVERY game server onto the primary
301	  // node forever, regardless of its actual load. Confirmed live: every game
302	  // server in production had nodeId: null and primary sat at 84% real RAM /
303	  // 200% committed CPU while other nodes were comparatively idle.
304	  const node = await scheduleNode(quote.ramMB);
305	
306	  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
307	  // path the wallet was credited the card leg first, so this holds.
308	  if (user.balanceCents < chargeCents) {
309	    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
310	  }
311	
312	  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
313	  const termLabel =
314	    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;
315	
316	  // Line-item description shared by the wallet-transaction memo and the invoice —
317	  // mirrors lib/order.ts's VPS line ("<plan> VPS (<hostname>) — <term>"), the
318	  // pattern lib/actions-hosting.ts and lib/actions-email-hosting.ts also follow.
319	  const invDesc = `${quote.planName} Game Server (${quote.hostname}) — ${termLabel}`;
320	
321	  let server;
322	  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
323	  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
324	  // null and emails nothing. Mirrors `orderInvoice` in lib/order.ts placeOrder.
325	  let orderInvoice: { id: string; number: number; amountCents: number } | null = null;
326	  try {
327	    server = await db.$transaction(async (tx) => {
328	      await debitWallet(tx, user.id, chargeCents);
329	      await tx.walletTransaction.create({
330	        data: {
331	          userId: user.id,
332	          amountCents: -chargeCents,
333	          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
334	        },
335	      });
336	      // Billing document for the charge — created inside the same debit tx so it
337	      // shares the transaction's atomicity (a rolled-back charge leaves no invoice),
338	      // exactly like lib/order.ts's VPS invoice and worker/billing.ts's renewal
339	      // invoice. Game has no promo/coupon/tax (see GameOrderPrice), so this is a
340	      // single line for the full charge.
341	      const createdInvoice = await tx.invoice.create({
342	        data: invoiceCreateData({
343	          userId: user.id,
344	          description: invDesc,
345	          status: "PAID",
346	          taxCents: 0,
347	          taxRatePercent: 0,
348	          taxCountry: null,
349	          period: { start: new Date(), end: addMonths(new Date(), quote.term) },
350	          lineItems: [{ description: invDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
351	        }),
352	      });
353	      orderInvoice = {
354	        id: createdInvoice.id,
355	        number: createdInvoice.number,
356	        amountCents: createdInvoice.amountCents,
357	      };
358	      const s = await tx.server.create({
359	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
360	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
361	        data: {
362	          name: quote.hostname,
363	          hostname: quote.hostname,
364	          label: quote.label,
365	          userId: user.id,
366	          planId: quote.basePlanId,
367	          gamePlanId: quote.gamePlanId,
368	          osTemplateId: quote.osTemplateId,
369	          // The customer's per-game setup, applied at the point of sale — the worker
370	          // renders these into the game's own config at provision (worker/game-config).
371	          gameVariant: quote.variant || null,
372	          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
373	          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
374	          // game branch renews monthlyCents × termMonths × (1 − annual).
375	          termMonths: quote.term,
376	          // No seasonal promo on game — this term was sold at 0% off, so any future
377	          // proration prices against full price.
378	          termPromoPercent: 0,
379	          // The annual rate frozen at sale, so the renewal bills the SAME price the
380	          // order charged even if the admin retunes annual_discount_percent later.
381	          annualDiscountPct: quote.annualPct,
382	          nodeId: node?.id ?? null,
383	          wantsDedicatedIp: false,
384	          expiresAt: addMonths(new Date(), quote.term),
385	        } as Prisma.ServerUncheckedCreateInput,
386	      });
387	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
388	      return s;
389	    });
390	  } catch (e) {
391	    if (e instanceof InsufficientBalanceError) {
392	      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
393	    }
394	    throw e;
395	  }
396	
397	  await db.auditLog.create({
398	    data: {
399	      userId: user.id,
400	      action: "gameserver.order",
401	      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
402	    },
403	  });
404	  // Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
405	  // place a game order is created & paid, reached by BOTH the wallet path
406	  // (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts webhook /
407	  // redirect), so every completed game deploy is counted once with a reliable userId.
408	  // Terminal event (drives the completed counts, not a wizard-step row); best-effort
409	  // and double-guarded so it can never disturb the money path.
410	  try {
411	    await recordDeployFunnelComplete({ product: "game", step: "Complete", stepIndex: 5, userId: user.id });
412	  } catch {
413	    /* never let funnel bookkeeping affect a completed order */
414	  }
415	  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
416	  // the money has already moved, so a mail failure must NEVER surface as an order
417	  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
418	  // path (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts)
419	  // because both go through this one placeGameOrder — mirrors lib/order.ts placeOrder
420	  // and lib/actions-email-hosting.ts orderEmailHostingCore. Read via the declared
421	  // union — the value is assigned inside the $transaction callback, which TS
422	  // control-flow analysis does not track, so a direct read would narrow to `null`.
423	  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number } | null;
424	  if (invForEmail) {
425	    try {
426	      const { sendMail, emails } = await import("./mailer");
427	      const branding = await invoiceBranding();
428	      const tpl = emails.invoiceNew(
429	        {
430	          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
431	          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
432	          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
433	          description: invDesc,
434	        },
435	        true, // the itemised PDF is attached (invoiceId passed below)
436	      );
437	      await sendMail({
438	        to: user.email,
439	        subject: tpl.subject,
440	        html: tpl.html,
441	        template: tpl.template,
442	        invoiceId: invForEmail.id,
443	        userId: user.id,
444	        kind: "invoice",
445	      });
446	    } catch {
447	      /* invoice email is best-effort — a placed order must never fail on mail */
448	    }
449	  }
450	  return server.id;
451	}
