1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import { Prisma } from "@prisma/client";
6	import type { User } from "@prisma/client";
7	import { db } from "./db";
8	import { debitWallet, InsufficientBalanceError } from "./wallet";
9	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
10	import { annualDiscountPct } from "./annual-discount";
11	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
12	import { capacityCheck, diskCapacityCheck } from "./capacity";
13	import { invoiceCreateData, invoiceBranding, formatInvoiceNumber } from "./invoices";
14	import { maybeRewardReferral } from "./actions-growth";
15	import { accrueRecentCommissionsForCustomer } from "./partner-commission";
16	import { currentPromo } from "./promotions";
17	import {
18	  introFirstTermDiscountCents,
19	  introSoldPercent,
20	  planIntroMonthlyCents,
21	  planIntroTermMonths,
22	} from "./intro-pricing";
23	import {
24	  claimFirstMonthFree,
25	  confirmReservation,
26	  firstMonthFreeEnabled,
27	  firstMonthFreeAppliesTo,
28	  setPromoOrderRef,
29	} from "./promo-redemption";
30	import { extraDiskPerGbCents } from "./disk-expand";
31	import {
32	  EXTRA_DISK_MAX_ADD_GB,
33	  EXTRA_DISK_MAX_TOTAL_GB,
34	  effectiveDiskGB,
35	  extraDiskCentsAt,
36	  extraDiskLabel,
37	  normalizeExtraDiskGB,
38	} from "./extra-disk";
39	import { getSettingBool, getSettingInt } from "./settings";
40	import { scheduleNode } from "./node-capacity";
41	import { taxContextForUser } from "./tax";
42	import { assertSpendCap, maybeAlertBudget, SpendCapError } from "./spend-caps";
43	import { couponOrderDiscountCents } from "./coupon-order";
44	import { confirmOrderCouponReservation, releaseExpiredCouponHoldsFor } from "./coupon-redemption";
45	import { backupPlusMonthlyCents } from "./backup-upgrade";
46	import {
47	  type BackupTier,
48	  backupTierMonthlyCents,
49	  backupTierSpec,
50	  normalizeBackupTier,
51	} from "./backup-tiers";
52	import { recordDeployFunnelComplete } from "./deploy-funnel";
53	
54	export class OrderError extends Error {}
55	
56	/**
57	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
58	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
59	 * torn down (DELETING). Returns an error message when the cap is reached, else
60	 * null.
61	 *
62	 * Lives in this PLAIN module rather than lib/actions.ts (a `"use server"` file)
63	 * for the same reason `gameOrderGate` lives in lib/game-order.ts: it takes an
64	 * already-resolved `userId` and does no session check of its own, so exporting
65	 * it from a Server Actions file would let a stranger probe any account's server
66	 * count with no authentication — exactly the class of bug
67	 * test/auth-lockouts.test.ts's "HAZARD" suite exists to catch. `payAndDeploy`
68	 * (lib/actions.ts) and the PayPal/Coinbase VPS-order action
69	 * (lib/actions-payment-providers.ts) both call this AFTER their own
70	 * `requireUser()`.
71	 */
72	export async function serverLimitError(userId: string): Promise<string | null> {
73	  const cap = await getSettingInt("max_servers_per_user", 10);
74	  if (cap <= 0) return null; // 0 (or negative) = unlimited
75	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
76	  if (owned >= cap) {
77	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
78	  }
79	  return null;
80	}
