246	    planId: String(formData.get("planId") ?? ""),
247	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
248	    hostname: String(formData.get("hostname") ?? ""),
249	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
250	    addonMalware: formData.get("addon_malware") === "1",
251	    addonBackup: formData.get("addon_backup") === "1",
252	    addonDocker: formData.get("addon_docker") === "1",
253	    termMonths: Number(formData.get("termMonths") ?? 1),
254	    dedicatedIp: formData.get("dedicatedIp") === "1",
255	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
256	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
257	    free: formData.get("free") === "1",
258	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
259	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
260	    // bought so it drops out of JSON.stringify: the intent is round-tripped
261	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
262	    // createOrderCheckout), and every byte of headroom matters there.
