272	/**
273	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
274	 * a node this order would push to/past the CRITICAL capacity threshold when
275	 * another node has room. Falls back to primary (any node) when every candidate is
276	 * already critical — the scheduler never REFUSES an order for a capacity warning
277	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
278	 * roomier node when one exists. DB-only so order placement never blocks on a
279	 * Proxmox round trip.
280	 */
281	/** Validate + price an order without placing it. Throws OrderError on any problem. */
282	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
283	  const parsed = orderSchema.safeParse(intent);
284	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
285	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
286	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
287	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
288	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
289	    throw new OrderError(
290	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
291	    );
292	  }
293	  const term = vpsTerm(Number(intent.termMonths ?? 1));
294	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
295	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
296	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
297	  const annualPct = await annualDiscountPct();
298	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
299	
300	  // Extra root disk, priced per GB/month and multiplied over the term exactly
301	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
302	  // promo — the customer pays the same $/GB whichever term they pick, and renews
303	  // at the same rate). Growth is one-way: this is permanent for the server.
304	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
305	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
306	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
307	  const extraDiskCents = extraDiskMonthlyCents * term.months;
308	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
309	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
310	  }
311	
312	  // Paid backup RETENTION tier, priced per month and multiplied over the term
313	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
314	  // the same $/mo whichever term or promo, and renews at the same rate through
315	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
316	  const backupTier = normalizeBackupTier(intent.backupTier);
317	  const backupMonthlyCents =
318	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
319	  const backupCents = backupMonthlyCents * term.months;
320	
321	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
322	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
323	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
324	  // real renewal price and this discounted value is the real first-term price.
325	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
326	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
327	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
328	
329	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
330	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
331	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
332	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
333	  // the regular term total (not a second price), so the regular term stays the one
334	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
335	  // every plan without an intro price, so the whole VPS flow below is unchanged for
336	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
337	  // so intro and FMF never stack here.
338	  const introMonthlyCents = planIntroMonthlyCents(plan);
339	  const introTermMonths = planIntroTermMonths(plan);
340	  const introDiscountCents = introFirstTermDiscountCents(
341	    plan.priceCents,
342	    introMonthlyCents,
343	    term.months,
344	    introTermMonths,
345	    annualPct,
346	  );
347	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
348	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
349	  // The rate this first term is sold at (percent off the regular term total) — stamped
350	  // on Server.termPromoPercent below via the promo object so proration/refunds price
351	  // against it exactly like a seasonal promo.
352	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
353	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
354	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
355	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
356	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
357	  // redemption machinery — an intro price has no per-account cap; it is simply this
358	  // plan's first-term price.
359	  const promo =
360	    introDiscountCents > 0
361	      ? {
362	          id: "intro-price",
363	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
364	          label: "Intro price",
365	          discountPercent: introPercent,
366	          firstMonthFree: false,
367	        }
368	      : currentPromo(new Date());
369	  // The promo is now MANAGED: the owner can switch it off, and every claim is
370	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
371	  // quote shows — and placeOrder charges — the full price, so display === charged
372	  // on the disabled path. When it is on, the quote shows the first-month-free
373	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
374	  // the credit is actually granted (a lost race there is charged full).
375	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
376	  // the card path uses it to re-quote for a customer who has already redeemed
377	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
378	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
379	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
380	  // false here and planFirstTermCents falls through to the regular term total.
381	  const promoEnabled =
382	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
383	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
384	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
385	  // YEARS free. So we subtract one month of the plan's rate from the term total.
386	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
387	  // 36-month term the customer pays the term minus one month. Renewals bill the
388	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
389	  const planFirstTermCents =
390	    promoEnabled && promo.firstMonthFree
391	      ? Math.max(0, regularPlanCents - plan.priceCents)
392	      : regularPlanCents;
393	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
394	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
395	  const promoCreditCents = regularPlanCents - planFirstTermCents;
396	
397	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
398	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
399	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
400	  // so the deploy preview can show it; the redemption itself (count + per-user +
401	  // per-IP guards) is claimed atomically in placeOrder.
402	  let couponId: string | null = null;
403	  let couponDiscountCents = 0;
404	  let couponLabel = "";
405	  let couponError = "";
406	  let couponMaxRedemptions: number | null = null;
407	  let couponFirstTimeOnly = false;
408	  const code = (intent.couponCode ?? "").trim().toUpperCase();
409	  if (code) {
410	    if (!(await getSettingBool("coupons_enabled", true))) {
411	      couponError = "Promo codes are currently disabled.";
412	    } else {
413	      const coupon = await db.coupon.findUnique({ where: { code } });
414	      if (!coupon) {
415	        couponError = "That code isn’t valid.";
416	      } else {
417	        const verdict = couponOrderDiscountCents(
418	          {
419	            kind: coupon.kind,
420	            value: coupon.value,
421	            serviceKind: coupon.serviceKind,
422	            planSlug: coupon.planSlug,
423	            maxTermMonths: coupon.maxTermMonths,
424	            active: coupon.active,
425	            expiresAt: coupon.expiresAt,
426	            maxRedemptions: coupon.maxRedemptions,
427	            timesRedeemed: coupon.timesRedeemed,
428	            minAmountCents: coupon.minAmountCents,
429	          },
430	          {
431	            serviceKind: "VPS",
432	            planSlug: plan.slug,
433	            planMonthlyCents: plan.priceCents,
434	            termMonths: term.months,
435	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
436	            // coupon cannot together drive the plan charge below zero, and a percentage
437	            // coupon is honestly "% off what you actually pay this term".
438	            planChargeCents: introFirstTermPlanCents,
439	          },
440	          new Date(),
441	        );
442	        if (verdict.ok) {
443	          couponId = coupon.id;
444	          couponDiscountCents = verdict.discountCents;
445	          couponLabel = verdict.label;
446	          couponMaxRedemptions = coupon.maxRedemptions;
447	          couponFirstTimeOnly = coupon.firstTimeOnly;
448	        } else {
449	          couponError = verdict.error;
450	        }
451	      }
452	    }
453	  }
454	
455	  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
456	  return {
457	    plan,
458	    os,
459	    term,
460	    chargeCents,
461	    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
462	    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
463	    // is the plan-portion cash the first term is sold at; the monthly figures drive
464	    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
465	    introDiscountCents,
466	    introFirstTermPlanCents,
467	    introMonthlyCents,
468	    introTermMonths,
469	    introRenewalMonthly,
470	    introPercent,
471	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
472	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
473	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
474	    annualPct,
475	    promo,
476	    promoCreditCents,
477	    regularPlanCents,
478	    extraDiskGB,
479	    extraDiskMonthlyCents,
480	    extraDiskCents,
481	    backupTier,
482	    backupMonthlyCents,
483	    backupCents,
484	    couponId,
485	    couponDiscountCents,
486	    couponLabel,
487	    couponError,
488	    couponMaxRedemptions,
489	    couponFirstTimeOnly,
490	  };
491	}
