493	/**
494	 * Place an order: validate, charge the wallet (unless a free admin grant),
495	 * create the Server + PROVISION job. Returns the new server id. Does NOT
496	 * redirect. Callers must ensure funds exist (or pass free) — this still
497	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
498	 *
499	 * `sold` overrides the recomputed price with the one the order was actually SOLD
500	 * at — the card-paid path passes the figure stamped on the Checkout session
501	 * BEFORE the card was charged, so the confirm redirect settles the price the
502	 * customer consented to instead of re-pricing against whatever promo is running
503	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
504	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
505	 * quote, which it computed moments ago in the same request. See OrderPrice.
506	 */
507	/**
508	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
509	 * any failure so nothing partial survives. Kept separate from the order tx so a
510	 * wallet order can surface the failure before any money moves, and a card order
511	 * (already paid) can swallow it without stranding the paid provision.
512	 *
513	 * Guards, all enforced here: first-time-only (no prior paid server), the
514	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
515	 * (the two @@unique constraints on CouponRedemption).
516	 */
517	async function claimOrderCoupon(opts: {
518	  couponId: string;
519	  maxRedemptions: number | null;
520	  firstTimeOnly: boolean;
521	  userId: string;
522	  ipHash: string | null;
523	  amountCents: number;
524	}): Promise<void> {
525	  await db.$transaction(async (tx) => {
526	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
527	    // not stand between them and this coupon on a fresh (wallet) order — and its global
528	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
