556	/**
557	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
558	 *
559	 * The card leg discounts `cardCents` up front and only settles the redemption
560	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
561	 * paid provision is never stranded. Without this pre-check, a customer who has
562	 * already used a one-per-person code (or isn't first-time) still gets the
563	 * discounted card charge and the swallow hides it. So before we send them to
564	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
565	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
566	 * (a race could still lose the atomic claim at settle time — that path stays
567	 * swallowed by design), but it closes the everyday bypass.
568	 */
569	export async function orderCouponClaimable(opts: {
570	  couponId: string;
571	  firstTimeOnly: boolean;
572	  maxRedemptions: number | null;
573	  userId: string;
574	  ipHash: string | null;
575	}): Promise<{ ok: true } | { ok: false; error: string }> {
576	  if (opts.firstTimeOnly) {
577	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
578	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
579	  }
580	  const byUser = await db.couponRedemption.findUnique({
581	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
582	  });
583	  if (byUser) return { ok: false, error: "You’ve already used this code." };
584	  if (opts.ipHash) {
585	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
586	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
587	  }
588	  if (opts.maxRedemptions !== null) {
589	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
590	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
591	  }
592	  return { ok: true };
593	}
