971	      return s;
972	    });
973	  } catch (e) {
974	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
975	    throw e;
976	  }
977	
978	  await db.auditLog.create({
979	    data: {
980	      userId: user.id,
981	      action: "server.order",
982	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
983	    },
984	  });
985	  if (!freeRequested) {
986	    try {
987	      await maybeRewardReferral(user.id);
988	    } catch {
989	      /* non-fatal */
990	    }
991	    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
992	    // over the customer's budget. Best-effort — never fails an order.
993	    await maybeAlertBudget(user.id);
994	    // KOL/Agency partner commission: if this customer is attached to a partner,
995	    // accrue commission on the PAID order invoice now (idempotent; the background
996	    // sweep would otherwise catch it within minutes). Best-effort by design.
997	    await accrueRecentCommissionsForCustomer(user.id);
998	  }
999	  // Deploy-funnel COMPLETION — the authoritative, server-side bottom of the funnel.
1000	  // This is the ONE place a VPS order is definitively created & paid: both the wallet
1001	  // path (lib/actions.ts payAndDeploy) and the card path (lib/fulfil-checkout.ts, run
1002	  // by the Stripe webhook or the success redirect) reach it, so recording here counts
1003	  // every completed VPS deploy exactly once, with a reliable `userId`. The step index
1004	  // orders it at the tail (after Review/Payment); the completion is a terminal event,
1005	  // not a wizard step, so it drives the completed counts rather than rendering a row.
1006	  // Best-effort AND double-guarded: `recordDeployFunnelComplete` already swallows every
1007	  // failure, and the extra catch guarantees analytics can never disturb the money path.
1008	  try {
1009	    await recordDeployFunnelComplete({ product: "vps", step: "Complete", stepIndex: 8, userId: user.id });
1010	  } catch {
1011	    /* never let funnel bookkeeping affect a completed order */
1012	  }
1013	  // Email the paid ORDER invoice with its PDF attached. Best-effort AND post-commit:
1014	  // the money has already moved, so a mail failure must NEVER surface as an order
1015	  // failure. Fires exactly once per order (single commit) and covers BOTH the wallet
1016	  // path (lib/actions.ts) and the card path (lib/fulfil-checkout.ts) because both go
1017	  // through this one placeOrder. This is the invoice DOCUMENT — deliberately
1018	  // `invoiceNew` (subject "Invoice #… — $… due"), not `receipt`, so it does not
1019	  // collide with the separate "Payment received" wallet/card top-up receipt a card
1020	  // order already gets from lib/stripe.ts. Passing `invoiceId` + the `invoice_new`
1021	  // template makes lib/mailer.ts auto-attach the rendered PDF. `orderInvoice` is null
1022	  // for free admin grants (no invoice created), so those email nothing.
1023	  // Read via the declared union — the value is assigned inside the $transaction
1024	  // callback, which TS control-flow analysis does not track, so a direct read would
1025	  // narrow to `null`.
1026	  const invForEmail = orderInvoice as { id: string; number: number; amountCents: number; description: string } | null;
1027	  if (invForEmail) {
1028	    try {
1029	      const { sendMail, emails } = await import("./mailer");
1030	      const branding = await invoiceBranding();
1031	      const tpl = emails.invoiceNew(
1032	        {
1033	          invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
1034	          amount: `$${(invForEmail.amountCents / 100).toFixed(2)}`,
1035	          dueDate: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
1036	          description: invForEmail.description,
1037	        },
1038	        true, // the itemised PDF is attached (invoiceId passed below)
1039	      );
1040	      await sendMail({
1041	        to: user.email,
1042	        subject: tpl.subject,
1043	        html: tpl.html,
1044	        template: tpl.template,
1045	        invoiceId: invForEmail.id,
1046	        userId: user.id,
1047	        kind: "invoice",
1048	      });
1049	    } catch {
1050	      /* invoice email is best-effort — a placed order must never fail on mail */
1051	    }
1052	  }
1053	  return server.id;
