146	/**
147	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
148	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
149	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
150	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
151	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
152	 *
153	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
154	 * amount the customer paid into their wallet at checkout so the debit here nets to
155	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
156	 * spend the just-credited funds). The wallet path omits it and debits the quote.
157	 */
158	export async function applyResize(opts: {
159	  serverId: string;
160	  planId: string;
161	  actorUserId: string;
162	  chargeCents?: number;
163	}): Promise<void> {
164	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
165	  const prorateCents = opts.chargeCents ?? quoted;
166	
167	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
168	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
169	
170	  try {
171	    await db.$transaction(async (tx) => {
172	      if (prorateCents > 0) {
173	        await debitWallet(tx, server.userId, prorateCents);
174	        await tx.walletTransaction.create({
175	          data: {
176	            userId: server.userId,
177	            amountCents: -prorateCents,
178	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
179	          },
180	        });
181	        // PAID invoice for the proration charge (one per user-initiated resize).
182	        await tx.invoice.create({
183	          data: invoiceCreateData({
184	            userId: server.userId,
185	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
186	            status: "PAID",
187	            lineItems: [
188	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
189	            ],
190	          }),
191	        });
192	      }
193	      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
194	      // not re-base the term — `expiresAt` is untouched and no new months are sold —
195	      // it only moves the customer to a different plan at the rate they already
196	      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
197	      // to zero: both halves read the same stored basis. (This is also why the basis
198	      // is stored as a percent rather than a $/mo figure: a cents rate would have to
199	      // be rewritten here, and that rewrite is one more place to get it wrong.)
200	      //
201	      // Record the amount charged on the job so the worker's RESIZE handler can
202	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
203	      // resize terminally fails — money is committed here, before the job runs.
204	      await tx.job.create({
205	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
206	      });
207	      await tx.auditLog.create({
208	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
209	      });
210	    });
211	  } catch (e) {
212	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
213	    throw e;
214	  }
215	}
