cd /opt/nxeon-wip-custom-plans && node -e '
// Solve least squares for price = a*cpu + b*ramGB + c*diskGB (deltas, no intercept)
// using the three adjacent-tier deltas from the plan ladder.
const rows = [
  {cpu:1, ram:2, disk:25, price:411},   // Starter -> Standard
  {cpu:1, ram:4, disk:30, price:800},   // Standard -> Pro
  {cpu:1, ram:8, disk:40, price:1200},  // Pro -> Max
];

// Build X^T X and X^T y
const X = rows.map(r => [r.cpu, r.ram, r.disk]);
const y = rows.map(r => r.price);

function matT(A){ const r=A.length,c=A[0].length; const T=Array.from({length:c},()=>Array(r).fill(0)); for(let i=0;i<r;i++)for(let j=0;j<c;j++)T[j][i]=A[i][j]; return T; }
function matMul(A,B){ const r=A.length,k=B.length,c=B[0].length; const R=Array.from({length:r},()=>Array(c).fill(0)); for(let i=0;i<r;i++)for(let j=0;j<c;j++){let s=0;for(let l=0;l<k;l++)s+=A[i][l]*B[l][j]; R[i][j]=s;} return R; }
function matVec(A,v){ return A.map(row=>row.reduce((s,a,i)=>s+a*v[i],0)); }
function solve3(A,b){
  // Cramer rule for 3x3
  const det=(m)=>m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);
  const D=det(A);
  const Ai=(col)=>A.map((row,i)=>row.map((v,j)=> j===col? b[i]: v));
  return [0,1,2].map(col=>det(Ai(col))/D);
}
const Xt=matT(X);
const XtX=matMul(Xt,X);
const Xty=matVec(Xt,y);
const beta=solve3(XtX,Xty);
console.log("least squares [perCpu, perRamGB, perDiskGB] cents:", beta);

// residuals
rows.forEach(r=>{
  const pred=beta[0]*r.cpu+beta[1]*r.ram+beta[2]*r.disk;
  console.log("delta actual", r.price, "predicted", pred.toFixed(2));
});
'

