// Pure pricing + guardrail math for CUSTOM VPS / game-server specs — servers
// bigger than the biggest premade plan ("Max"). No DB, no server-only imports:
// this is the ONE formula shared by the client-side deploy wizards (instant price
// as a slider moves, no round trip) and the server-side quote/order path
// (lib/custom-plan.ts, which re-validates everything here before a Plan row is
// ever created — a client-computed price is never trusted for money).
//
// ─── WHY "CUSTOM" EXISTS ─────────────────────────────────────────────────────
// The premade ladder tops out at Max (4 vCPU / 16 GB / 120 GB). A customer who
// needs more than that on ANY dimension gets a one-off Plan row sized exactly to
// what they asked for (see lib/custom-plan.ts createCustomPlan) instead of being
// turned away or overpaying for a fixed "XL" tier that's still too small. So a
// valid custom spec is, by definition, Max-or-bigger on every dimension and
// STRICTLY bigger on at least one — never a way to buy something Max-sized (or
// smaller) at a different price, which would undercut the catalog and break the
// price-monotonic / disk-monotonic invariants lib/resize.ts depends on to keep
// upgrades honest.
//
// ─── PRICING FORMULA DERIVATION ──────────────────────────────────────────────
// The live ladder (prisma — Plan table) and its price DELTAS between adjacent
// tiers:
//
//   Tier      vCPU  RAM(GB)  Disk(GB)  Price      Δ vCPU  Δ RAM  Δ Disk  Δ Price
//   Starter     1      2        25     $8.88
//   Standard    2      4        50    $12.99        1       2      25    411¢
//   Pro         3      8        80    $20.99        1       4      30    800¢
//   Max         4     16       120    $32.99        1       8      40   1200¢
//
// A pure 3-variable linear fit (price = a·Δvcpu + b·Δram_GB + c·Δdisk_GB) across
// those three deltas turns out to be OVER-determined in a way the real ladder
// can't satisfy exactly: solving any two of the three delta-equations for
// (a, b, c) and checking against the third leaves a residual (405¢ vs 800¢ i.e
// disk-GB deltas here are exactly `20*Δvcpu + 2.5*Δram_GB`, so the three price
// points don't sit on a single consistent (a,b,c) — there's no clean 3-variable
// exact solution, only a best fit). So rather than force an unstable joint
// regression across three highly-correlated columns (cpu/ram/disk all grow
// together tier-to-tier), we ANCHOR the disk rate to a number the platform
// already charges for exactly this resource — `extra_disk_gb_price_cents`
// (lib/disk-expand.ts / lib/settings.ts), the live $0.10/GB/month a customer on
// ANY premade plan already pays to add root disk beyond their plan's included
// amount. Reusing it here means a GB of disk costs the same $ whether it comes
// from the extra-disk upsell or from building a custom plan — one number, one
// meaning, platform-wide.
//
// With disk fixed at that rate (10¢/GB), each tier-to-tier price delta minus its
// disk contribution attributes the REMAINDER to cpu + ram:
//
//   Standard-Starter: 411 - 10·25 = 161 = 1a + 2b
//   Pro-Standard:      800 - 10·30 = 500 = 1a + 4b
//   Max-Pro:          1200 - 10·40 = 800 = 1a + 8b
//
// Least-squares fit of those three (a, b) equations (normal equations
// 3a+14b=1461, 14a+84b=8722) solves EXACTLY to a = 11, b = 102 — i.e. $0.11 per
// extra vCPU/month and $1.02 per extra GB RAM/month. (RAM dominates the ladder's
// price growth far more than CPU does, which matches lib/capacity.ts's own
// framing of RAM as "the scarce resource" the platform oversells carefully
// while CPU is comparatively cheap to add.)
//
// All three rates are admin-tunable via lib/settings.ts (`custom_plan_per_vcpu_cents`,
// `custom_plan_per_ram_gb_cents`; disk reuses the existing `extra_disk_gb_price_cents`)
// so the catalog can be retuned without a redeploy if the premade ladder ever moves.
export const CUSTOM_PLAN_DEFAULT_RATES: CustomPlanRates = {
  perVcpuCents: 11,
  perRamGbCents: 102,
  perDiskGbCents: 10, // mirrors extra_disk_gb_price_cents's shipped default
};

/** Sane platform-wide ceiling — deliberately generous (nothing in the premade
 *  catalog approaches this), but not infinite: a real physical node has to be
 *  able to hold it. Admin-tunable via lib/settings.ts (custom_plan_max_*). */
export const CUSTOM_PLAN_DEFAULT_CEILING: CustomPlanCeiling = {
  maxCpuCores: 32,
  maxRamMB: 128 * 1024,
  maxDiskGB: 2000,
};

export type CustomPlanSpec = { cpuCores: number; ramMB: number; diskGB: number };

/** The floor a custom spec must clear on every dimension — today, the live "Max"
 *  plan's specs (see lib/custom-plan.ts customPlanFloor, which reads it from the
 *  DB rather than hardcoding it, so a future catalog change is picked up live). */
export type CustomPlanFloor = {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  priceCents: number;
  bandwidthTB: number;
};

export type CustomPlanCeiling = { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };

export type CustomPlanRates = { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };

/**
 * The custom-plan price: Max's price plus the per-unit rate for whatever exceeds
 * Max on each dimension. Only the EXCESS over the floor is charged for — a spec
 * that matches Max on RAM/disk but asks for double the CPU pays only for the
 * extra CPU, not a second copy of Max's whole price.
 *
 * Defensively clamped to STRICTLY more than the floor's price: a valid spec
 * (per validateCustomPlanSpec) always exceeds the floor on at least one
 * dimension, so with positive rates this clamp is a no-op — but if an admin ever
 * zeroes a rate (e.g. sets `extra_disk_gb_price_cents` to "0"), a disk-only
 * custom spec must still never price at-or-below Max, which would silently
 * undercut the catalog (the exact class of bug lib/resize.ts's price-monotonic
 * guard exists to prevent one level up, at resize time).
 */
export function computeCustomPlanPriceCents(
  spec: CustomPlanSpec,
  floor: CustomPlanFloor,
  rates: CustomPlanRates,
): number {
  const extraCpu = Math.max(0, spec.cpuCores - floor.cpuCores);
  const extraRamGB = Math.max(0, (spec.ramMB - floor.ramMB) / 1024);
  const extraDiskGB = Math.max(0, spec.diskGB - floor.diskGB);
  const raw =
    floor.priceCents +
    extraCpu * rates.perVcpuCents +
    extraRamGB * rates.perRamGbCents +
    extraDiskGB * rates.perDiskGbCents;
  return Math.max(Math.round(raw), floor.priceCents + 1);
}

/**
 * Guardrails: every dimension must be at or above the floor (never a way to buy
 * something Max-sized or smaller under a different name) and at or below the
 * admin-configured ceiling. A spec that matches the floor EXACTLY on all three
 * dimensions is rejected too — that's just Max, not a custom order.
 */
export function validateCustomPlanSpec(
  spec: CustomPlanSpec,
  floor: CustomPlanFloor,
  ceiling: CustomPlanCeiling,
): { ok: true } | { ok: false; reason: string } {
  if (!Number.isFinite(spec.cpuCores) || !Number.isFinite(spec.ramMB) || !Number.isFinite(spec.diskGB)) {
    return { ok: false, reason: "Invalid configuration." };
  }
  if (spec.cpuCores < floor.cpuCores || spec.ramMB < floor.ramMB || spec.diskGB < floor.diskGB) {
    return {
      ok: false,
      reason:
        `A custom server can't go below ${floor.cpuCores} vCPU / ${floor.ramMB / 1024} GB RAM / ${floor.diskGB} GB disk ` +
        `on any dimension — for anything smaller, pick a plan above instead.`,
    };
  }
  if (spec.cpuCores > ceiling.maxCpuCores || spec.ramMB > ceiling.maxRamMB || spec.diskGB > ceiling.maxDiskGB) {
    return {
      ok: false,
      reason:
        `Custom servers top out at ${ceiling.maxCpuCores} vCPU / ${ceiling.maxRamMB / 1024} GB RAM / ` +
        `${ceiling.maxDiskGB} GB disk — contact support for anything larger.`,
    };
  }
  if (spec.cpuCores === floor.cpuCores && spec.ramMB === floor.ramMB && spec.diskGB === floor.diskGB) {
    return { ok: false, reason: "That's exactly the Max plan — choose Max above instead of building custom." };
  }
  return { ok: true };
}

/** Clamp an arbitrary (e.g. slider-dragged, or player-count-derived) spec into the
 *  floor..ceiling range, rounding to whole units. Used by the UI so a slider or a
 *  recommendation can never even VISUALLY suggest an invalid spec. */
export function clampCustomPlanSpec(
  spec: CustomPlanSpec,
  floor: CustomPlanFloor,
  ceiling: CustomPlanCeiling,
): CustomPlanSpec {
  return {
    cpuCores: Math.min(ceiling.maxCpuCores, Math.max(floor.cpuCores, Math.round(spec.cpuCores))),
    ramMB: Math.min(ceiling.maxRamMB, Math.max(floor.ramMB, Math.round(spec.ramMB))),
    diskGB: Math.min(ceiling.maxDiskGB, Math.max(floor.diskGB, Math.round(spec.diskGB))),
  };
}

/** Human name for the one-off Plan/GamePlan row this spec becomes. */
export function customPlanName(spec: CustomPlanSpec): string {
  const ramGB = Math.round(spec.ramMB / 1024);
  return `Custom ${spec.cpuCores} vCPU / ${ramGB} GB / ${spec.diskGB} GB Disk`;
}

/** Slug pattern mirrors the one pre-existing manual precedent ("custom-4c8g-hmcebh")
 *  — short enough to stay under adminSavePlan's 30-char slug cap even at the
 *  ceiling's largest specs. `suffix` is a short random string the caller supplies
 *  (lib/custom-plan.ts) so this module stays free of any randomness/DB concerns. */
export function customPlanSlug(spec: CustomPlanSpec, suffix: string): string {
  const ramGB = Math.round(spec.ramMB / 1024);
  return `custom-${spec.cpuCores}c${ramGB}g-${suffix}`.slice(0, 30);
}

// Player-count → recommended resources, per game family. Pure/client-safe (no DB,
// no server-only imports) so the game deploy wizard's "how many players?" slider
// can compute a live recommendation with no round trip, the same way
// lib/custom-plan-pricing.ts prices the raw CPU/RAM/disk sliders.
//
// ─── DERIVATION ───────────────────────────────────────────────────────────────
// Every family already has 2-3 REAL, shipped tiers in the catalog (prisma/
// seed-gameplans.ts, seed-wave1-games.ts, seed-wave2-games.ts), each with actual
// ramMB/cpuCores/diskGB paired with a player-slot count. Rather than invent numbers
// from scratch, each family's curve below is a least-squares linear fit
// (resources = base + perPlayer × players) over that family's OWN seeded tiers —
// so within (and near) the range the catalog already sells, these numbers are
// GROUNDED in real, already-published specs, not guesses.
//
// Extrapolating the fitted line far PAST a family's largest seeded tier is where
// confidence drops — a straight line fit to 2-3 points at the low end is a rough
// estimate of what a much bigger population needs, not a measurement. That's
// exactly the case this slider exists for (a customer past the top of the normal
// tier ladder), so `maxSeededSlots` is recorded on every curve and
// `playerSliderMax` caps the slider at 5x it — generous enough to be useful for a
// genuinely large deployment, conservative enough that the recommendation is
// still a multiple-not-orders-of-magnitude extrapolation. See the design report
// for exactly which families' HIGH-player-count numbers are the least certain
// (the ones with only 2 seeded tiers, or a small `maxSeededSlots`) — the owner
// should sanity-check those before this ships, same as any new pricing surface.
//
// The recommendation is always a DEFAULT-SETTER, never a constraint: the caller
// (GameDeployWizard) applies it through clampCustomPlanSpec, so it can never
// itself produce a spec below the custom-plan floor (Max) or above the ceiling —
// the customer can still freely drag the underlying CPU/RAM/disk sliders above or
// below whatever this suggests.
import type { GameFamily } from "./games";

export type GameResourceSpec = { cpuCores: number; ramMB: number; diskGB: number };

type PlayerCurve = {
  ramBaseMB: number;
  ramPerPlayerMB: number;
  cpuBaseCores: number;
  cpuPerPlayer: number;
  diskBaseGB: number;
  diskPerPlayerGB: number;
  /** Largest slot count actually sold today for this family (see derivation note). */
  maxSeededSlots: number;
};

/**
 * Per-family curves, fitted from the live seeded catalog. Confidence notes:
 *
 * WELL-GROUNDED (3 seeded tiers spanning a wide slot range, so the fit is a real
 * interpolation more than an extrapolation): minecraft, rust, ark, satisfactory,
 * projectzomboid, sdtd, vrising, enshrouded, factorio, gmod, conan.
 *
 * ROUGHER (only 2 seeded tiers — the line is fixed by just two points, so treat
 * the slope itself as a reasonable-but-unverified estimate): valheim, palworld,
 * cs2, terraria, unturned, theforest, sonsoftheforest, bedrock.
 *
 * `enshrouded`'s raw 3-point least-squares fit produced a negative RAM/CPU
 * intercept (a fitting artifact, not a real "negative base machine") — clamped to
 * 0 here rather than left to produce a nonsensical recommendation at low player
 * counts.
 */
export const GAME_PLAYER_CURVES: Record<GameFamily, PlayerCurve> = {
  minecraft: { ramBaseMB: 788, ramPerPlayerMB: 150, cpuBaseCores: 1.6, cpuPerPlayer: 0.027, diskBaseGB: 14, diskPerPlayerGB: 0.73, maxSeededSlots: 50 },
  valheim: { ramBaseMB: 0, ramPerPlayerMB: 410, cpuBaseCores: 1, cpuPerPlayer: 0.1, diskBaseGB: 10, diskPerPlayerGB: 2, maxSeededSlots: 20 },
  rust: { ramBaseMB: 2436, ramPerPlayerMB: 53, cpuBaseCores: 1.67, cpuPerPlayer: 0.016, diskBaseGB: 33, diskPerPlayerGB: 0.32, maxSeededSlots: 150 },
  palworld: { ramBaseMB: 5461, ramPerPlayerMB: 341, cpuBaseCores: 2.67, cpuPerPlayer: 0.042, diskBaseGB: 40, diskPerPlayerGB: 1.25, maxSeededSlots: 32 },
  cs2: { ramBaseMB: 0, ramPerPlayerMB: 171, cpuBaseCores: 1, cpuPerPlayer: 0.083, diskBaseGB: 30, diskPerPlayerGB: 0.83, maxSeededSlots: 24 },
  terraria: { ramBaseMB: 0, ramPerPlayerMB: 256, cpuBaseCores: 0, cpuPerPlayer: 0.125, diskBaseGB: 10, diskPerPlayerGB: 1.25, maxSeededSlots: 16 },
