input.content:
// Server-side quote/creation path for CUSTOM VPS + game-server specs — plain
// module (not "use server"), mirroring lib/order.ts / lib/game-order.ts: it does
// real DB reads/writes but is called FROM "use server" actions that own the
// session check (lib/actions-custom-plan.ts), never exported to the network
// directly (see lib/order.ts's serverLimitError doc for why that split matters).
//
// The pure formula/guardrail math lives in lib/custom-plan-pricing.ts (no DB, so
// the client-side deploy wizards can price a slider move instantly); this file
// wraps it with the DB-backed floor/ceiling/rate resolution and the REAL
// capacity check, then creates the one-off `Plan` (+ `GamePlan`, for a game
// order) row a custom order actually buys.
import { db } from "./db";
import { getSettingInt } from "./settings";
import { extraDiskPerGbCents } from "./disk-expand";
import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
import { scheduleNode } from "./node-capacity";
import {
  type CustomPlanCeiling,
  type CustomPlanFloor,
  type CustomPlanRates,
  type CustomPlanSpec,
  CUSTOM_PLAN_DEFAULT_CEILING,
  CUSTOM_PLAN_DEFAULT_RATES,
  computeCustomPlanPriceCents,
  customPlanName,
  customPlanSlug,
  validateCustomPlanSpec,
} from "./custom-plan-pricing";

export class CustomPlanError extends Error {}

/**
 * Sort-order convention already established by the ONE pre-existing manual
 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
 * created before this feature existed for a one-off customer accommodation).
 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
 * comment on `Plan.nxcloudPlans`); 999 is reserved for one-off custom rows. Both
 * ranges keep `customPlanFloor` below from ever picking up an NxCloud sizing plan
 * or (worse) a PREVIOUS custom order's own Plan row as "Max".
 */
const CUSTOM_PLAN_SORT_ORDER = 999;
const CATALOG_SORT_ORDER_CEILING = 900;

/**
 * The floor every custom spec must clear: the current top-priced ACTIVE premade
 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
 * catalog change (a new tier added above Max) is picked up automatically with no
 * code change here.
 */
export async function customPlanFloor(): Promise<CustomPlanFloor> {
  const top = await db.plan.findFirst({
    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
    orderBy: { priceCents: "desc" },
  });
  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
  return {
    cpuCores: top.cpuCores,
    ramMB: top.ramMB,
    diskGB: top.diskGB,
    priceCents: top.priceCents,
    bandwidthTB: top.bandwidthTB,
  };
}

/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
  ]);
  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
}

/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
 *  $/GB the extra-disk upsell already charges on a premade plan — see the
 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
export async function customPlanRates(): Promise<CustomPlanRates> {
  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
    extraDiskPerGbCents(),
  ]);
  return { perVcpuCents, perRamGbCents, perDiskGbCents };
}

export type CustomPlanQuote =
  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };

/** Validate + price a custom spec without creating anything. Never throws — a bad
 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
  const [floor, ceiling, rates] = await Promise.all([customPlanFloor(), customPlanCeiling(), customPlanRates()]);
  const v = validateCustomPlanSpec(spec, floor, ceiling);
  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
  return { ok: true, floor, ceiling, rates, priceCents };
}

/**
 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
 * diskCapacityCheck is the identical function). A custom spec can ask for more
 * RAM than ANY catalog plan, so it must be screened the same way — this is not
 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
 * of a `Plan` row backing it.
 */
export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
  const ramOk = await capacityCheckRamMB(spec.ramMB);
  if (!ramOk.ok) return ramOk;
  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
  // check below runs against a real candidate node's pool, not "any node".
  const node = await scheduleNode(spec.ramMB);
  if (!node) {
    return { ok: false, reason: "No node currently has room for a server this size. Please contact support." };
  }
  return diskCapacityCheck(node.id, spec.diskGB);
}

/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
 *  shape ("custom-4c8g-hmcebh"). */
function randSuffix(n = 6): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

export type CreatedCustomPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

/**
 * Create ONE real `Plan` row for this exact spec — the same manual-accommodation
 * pattern already proven in production once (see the sort-order doc comment
 * above), now automated. Re-validates guardrails AND capacity from scratch (a
 * client-supplied price/spec is never trusted for money — mirrors every other
 * quote→place split in this codebase) before writing anything.
 *
 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
 * (every page that lists plans filters `active: true` — see
 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
 * order's Server row points at. From here on, every downstream money path
 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
 * like it does for a premade plan — no special-casing needed anywhere else.
 */
export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
  const quote = await customPlanQuote(spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(spec);
  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");

  let lastErr: unknown;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const plan = await db.plan.create({
        data: {
          slug: customPlanSlug(spec, randSuffix()),
          name: customPlanName(spec),
          cpuCores: spec.cpuCores,
          ramMB: spec.ramMB,
          diskGB: spec.diskGB,
          bandwidthTB: quote.floor.bandwidthTB,
          priceCents: quote.priceCents,
          storageTier: "nvme",
          active: false,
          sortOrder: CUSTOM_PLAN_SORT_ORDER,
        },
      });
      return {
        id: plan.id,
        name: plan.name,
        cpuCores: plan.cpuCores,
        ramMB: plan.ramMB,
        diskGB: plan.diskGB,
        bandwidthTB: plan.bandwidthTB,
        priceCents: plan.priceCents,
        storageTier: plan.storageTier,
      };
    } catch (e) {
      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
    }
  }
  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
}

export type CreatedCustomGamePlan = {
  plan: CreatedCustomPlan;
  gamePlanId: string;
  name: string;
  priceCents: number;
  slots: number | null;
};

/**
 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that
 * rides on top of the freshly-created base `Plan`, exactly like every premade
 * game tier already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
 * Priced at the SAME cents the base custom Plan would cost; a custom order has
 * no admin in the loop to hand-pick a cheaper flat game price the way premade
 * tiers sometimes are (see lib/resize.ts's comment on game tiers typically being
 * sold below their base plan's price), so charging exactly the formula price is
 * the safe, unambiguous default.
 */
export async function createCustomGamePlan(opts: {
  spec: CustomPlanSpec;
  gameFamily: string;
  players?: number | null;
}): Promise<CreatedCustomGamePlan> {
  const plan = await createCustomPlan(opts.spec);
  const gp = await db.gamePlan.create({
    data: {
      gameFamily: opts.gameFamily,
      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
      ramMB: plan.ramMB,
      cpuCores: plan.cpuCores,
      diskGB: plan.diskGB,
      slots: opts.players ?? null,
      priceCents: plan.priceCents,
      termMonths: 1,
      basePlanId: plan.id,
      active: false,
      sortOrder: CUSTOM_PLAN_SORT_ORDER,
    },
  });
  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
}

"use server";

// "use server" surface for the custom-plan builder — every export here is a
// public network endpoint the moment it exists, so EVERY one starts with its own
// `requireUser()` (see lib/order.ts serverLimitError's doc for exactly why a
// helper that skips this is a HAZARD test/auth-lockouts.test.ts exists to catch).
//
// This module owns no money movement: `confirmCustomPlanAction` /
// `confirmCustomGamePlanAction` only create the one-off catalog row (a real
// `Plan`/`GamePlan`, see lib/custom-plan.ts) the customer then buys through the
// EXACT same `payAndDeploy` / `payAndDeployGame` path every premade plan uses —
// so the actual charge, capacity re-check, wallet debit and invoice are all
// handled by code this feature does not touch at all.
import { z } from "zod";
import { requireUser, assertNotImpersonating } from "./auth";
import { GAME_FAMILIES } from "./games";
import {
  CustomPlanError,
  createCustomGamePlan,
  createCustomPlan,
  customPlanCapacityCheck,
  customPlanQuote,
} from "./custom-plan";

const specSchema = z.object({
  cpuCores: z.coerce.number().int().min(1).max(4096),
  ramMB: z.coerce.number().int().min(1).max(8 * 1024 * 1024),
  diskGB: z.coerce.number().int().min(1).max(1_000_000),
});

export type CustomPlanQuoteResult = {
  ok: boolean;
  error?: string;
  priceCents?: number;
  floor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };
  ceiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
  capacityOk?: boolean;
  capacityReason?: string;
};

/**
 * Read-only live quote for the deploy wizard's custom-spec sliders — the
 * AUTHORITATIVE price/guardrail/capacity check, run right before the customer is
 * allowed to confirm a custom spec (the client-side computeCustomPlanPriceCents
 * call that drives the slider's live number as it moves is a preview only; this
 * is what actually gates the "Use this custom plan" button).
 */
export async function quoteCustomPlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
}): Promise<CustomPlanQuoteResult> {
  await requireUser();
  const parsed = specSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  const quote = await customPlanQuote(parsed.data);
  if (!quote.ok) return { ok: false, error: quote.reason, floor: quote.floor, ceiling: quote.ceiling };
  const cap = await customPlanCapacityCheck(parsed.data);
  return {
    ok: true,
    priceCents: quote.priceCents,
    floor: quote.floor,
    ceiling: quote.ceiling,
    capacityOk: cap.ok,
    capacityReason: cap.reason,
  };
}

export type ConfirmedCustomPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

/**
 * Create the one-off VPS `Plan` row for this exact spec. Called ONCE, when the
 * customer commits to their custom build (not on every slider tick) — the
 * returned plan's `id` then flows through the wizard's existing `planId` state
 * exactly like picking any premade plan card, so Location/Install/Access/Review/
 * Payment need no changes at all.
 */
export async function confirmCustomPlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
}): Promise<{ ok: boolean; error?: string; plan?: ConfirmedCustomPlan }> {
  await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const parsed = specSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  try {
    const plan = await createCustomPlan(parsed.data);
    return { ok: true, plan };
  } catch (e) {
    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
  }
}

const gameConfirmSchema = specSchema.extend({
  gameFamily: z.enum(GAME_FAMILIES),
  players: z.coerce.number().int().min(1).max(1_000_000).optional(),
});

export type ConfirmedCustomGamePlan = {
  gamePlanId: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
};

/** Game analogue of `confirmCustomPlanAction` — creates the base `Plan` AND the
 *  `GamePlan` tier riding on it, returning the tier id the wizard drops straight
 *  into its existing `gamePlanId` hidden field. */
export async function confirmCustomGamePlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  gameFamily: string;
  players?: number;
}): Promise<{ ok: boolean; error?: string; tier?: ConfirmedCustomGamePlan }> {
  await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const parsed = gameConfirmSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  try {
    const created = await createCustomGamePlan({
      spec: { cpuCores: parsed.data.cpuCores, ramMB: parsed.data.ramMB, diskGB: parsed.data.diskGB },
      gameFamily: parsed.data.gameFamily,
      players: parsed.data.players ?? null,
    });
    return {
      ok: true,
      tier: {
        gamePlanId: created.gamePlanId,
        name: created.name,
        cpuCores: created.plan.cpuCores,
        ramMB: created.plan.ramMB,
        diskGB: created.plan.diskGB,
        slots: created.slots,
        priceCents: created.priceCents,
        termMonths: 1,
      },
    };
  } catch (e) {
    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  CUSTOM_PLAN_DEFAULT_CEILING,
  CUSTOM_PLAN_DEFAULT_RATES,
  clampCustomPlanSpec,
  computeCustomPlanPriceCents,
  customPlanName,
  customPlanSlug,
  validateCustomPlanSpec,
  type CustomPlanFloor,
} from "../lib/custom-plan-pricing.ts";

/**
 * The live "Max" plan, as of 2026-08-29 (prisma — Plan table): 4 vCPU / 16 GB /
 * 120 GB / $32.99. Every guardrail/pricing test below is anchored to this real
 * floor so a spec-drift in the catalog would show up here as a failing
 * assumption, not a silent wrong answer in production.
 */
const MAX: CustomPlanFloor = { cpuCores: 4, ramMB: 16384, diskGB: 120, priceCents: 3299, bandwidthTB: 8 };
const CEILING = CUSTOM_PLAN_DEFAULT_CEILING;
const RATES = CUSTOM_PLAN_DEFAULT_RATES;

test("a spec identical to Max is rejected — that's not custom, it's Max", () => {
  const v = validateCustomPlanSpec({ cpuCores: 4, ramMB: 16384, diskGB: 120 }, MAX, CEILING);
  assert.equal(v.ok, false);
});

test("below Max on ANY single dimension is rejected, even if others are bigger", () => {
  // CPU below floor, everything else huge.
  assert.equal(validateCustomPlanSpec({ cpuCores: 3, ramMB: 65536, diskGB: 500 }, MAX, CEILING).ok, false);
  // RAM below floor.
  assert.equal(validateCustomPlanSpec({ cpuCores: 8, ramMB: 8192, diskGB: 500 }, MAX, CEILING).ok, false);
  // Disk below floor.
  assert.equal(validateCustomPlanSpec({ cpuCores: 8, ramMB: 65536, diskGB: 100 }, MAX, CEILING).ok, false);
});

test("raising ONE dimension above Max while matching Max elsewhere is allowed", () => {
  // Max CPU/RAM but a bigger disk — the exact "even bigger disk" case called out
  // in the requirements as something that must NOT be forced to also bump CPU/RAM.
  const v = validateCustomPlanSpec({ cpuCores: 4, ramMB: 16384, diskGB: 500 }, MAX, CEILING);
  assert.equal(v.ok, true);
});

test("above the admin ceiling on any dimension is rejected", () => {
  assert.equal(
    validateCustomPlanSpec({ cpuCores: CEILING.maxCpuCores + 1, ramMB: MAX.ramMB, diskGB: MAX.diskGB }, MAX, CEILING).ok,
    false,
  );
  assert.equal(
    validateCustomPlanSpec({ cpuCores: MAX.cpuCores, ramMB: CEILING.maxRamMB + 1024, diskGB: MAX.diskGB }, MAX, CEILING).ok,
    false,
  );
  assert.equal(
    validateCustomPlanSpec({ cpuCores: MAX.cpuCores, ramMB: MAX.ramMB, diskGB: CEILING.maxDiskGB + 1 }, MAX, CEILING).ok,
    false,
  );
});

test("exactly at the ceiling on every dimension is allowed (boundary is inclusive)", () => {
  const v = validateCustomPlanSpec(
    { cpuCores: CEILING.maxCpuCores, ramMB: CEILING.maxRamMB, diskGB: CEILING.maxDiskGB },
    MAX,
    CEILING,
  );
  assert.equal(v.ok, true);
});

test("price at Max exactly is never computed (guarded upstream by validate), but if it ever were, price still exceeds Max", () => {
  const price = computeCustomPlanPriceCents({ cpuCores: MAX.cpuCores, ramMB: MAX.ramMB, diskGB: MAX.diskGB }, MAX, RATES);
  // No excess on any dimension — the raw formula would equal Max's price exactly;
  // the defensive +1 clamp must still push it strictly above.
  assert.ok(price > MAX.priceCents);
});

test("price formula: only the EXCESS over Max is charged for", () => {
  // +4 vCPU, +16 GB RAM, +80 GB disk over Max.
  const spec = { cpuCores: 8, ramMB: 32768, diskGB: 200 };
  const price = computeCustomPlanPriceCents(spec, MAX, RATES);
  const expected = MAX.priceCents + 4 * RATES.perVcpuCents + 16 * RATES.perRamGbCents + 80 * RATES.perDiskGbCents;
  assert.equal(price, expected);
  assert.ok(price > MAX.priceCents, "a custom spec must always price strictly above Max");
});

test("price formula: raising disk alone still prices strictly above Max", () => {
  const spec = { cpuCores: MAX.cpuCores, ramMB: MAX.ramMB, diskGB: MAX.diskGB + 50 };
  const price = computeCustomPlanPriceCents(spec, MAX, RATES);
  assert.equal(price, MAX.priceCents + 50 * RATES.perDiskGbCents);
  assert.ok(price > MAX.priceCents);
});

test("price formula is monotonic increasing in every dimension", () => {
  const base = computeCustomPlanPriceCents({ cpuCores: 8, ramMB: 32768, diskGB: 200 }, MAX, RATES);
  const moreCpu = computeCustomPlanPriceCents({ cpuCores: 9, ramMB: 32768, diskGB: 200 }, MAX, RATES);
  const moreRam = computeCustomPlanPriceCents({ cpuCores: 8, ramMB: 33792, diskGB: 200 }, MAX, RATES);
  const moreDisk = computeCustomPlanPriceCents({ cpuCores: 8, ramMB: 32768, diskGB: 210 }, MAX, RATES);
  assert.ok(moreCpu > base);
  assert.ok(moreRam > base);
  assert.ok(moreDisk > base);
});

test("a misconfigured $0 disk rate still can't price a disk-only custom spec at or below Max", () => {
  const zeroedRates = { ...RATES, perDiskGbCents: 0 };
  const spec = { cpuCores: MAX.cpuCores, ramMB: MAX.ramMB, diskGB: MAX.diskGB + 200 };
  const price = computeCustomPlanPriceCents(spec, MAX, zeroedRates);
  assert.ok(price > MAX.priceCents, "the defensive floor+1 clamp must still hold even with a zeroed rate");
});

test("clampCustomPlanSpec pulls an out-of-range spec back into floor..ceiling", () => {
  const clamped = clampCustomPlanSpec({ cpuCores: 1, ramMB: 512, diskGB: 5 }, MAX, CEILING);
  assert.deepEqual(clamped, { cpuCores: MAX.cpuCores, ramMB: MAX.ramMB, diskGB: MAX.diskGB });

  const clampedHigh = clampCustomPlanSpec(
    { cpuCores: 9999, ramMB: 9999 * 1024, diskGB: 9_999_999 },
    MAX,
    CEILING,
  );
  assert.deepEqual(clampedHigh, { cpuCores: CEILING.maxCpuCores, ramMB: CEILING.maxRamMB, diskGB: CEILING.maxDiskGB });
});

test("name and slug are stable, human-readable and slug fits the DB column cap", () => {
  const spec = { cpuCores: 8, ramMB: 32768, diskGB: 200 };
  assert.equal(customPlanName(spec), "Custom 8 vCPU / 32 GB / 200 GB Disk");
  const slug = customPlanSlug(spec, "abc123");
  assert.equal(slug, "custom-8c32g-abc123");
  // adminSavePlan's zod schema caps slug at 30 chars — even at the ceiling.
  const bigSlug = customPlanSlug({ cpuCores: CEILING.maxCpuCores, ramMB: CEILING.maxRamMB, diskGB: CEILING.maxDiskGB }, "abc123");
  assert.ok(bigSlug.length <= 30, `slug too long: ${bigSlug}`);
});

