import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";
import {
  GAME_PLAYER_CURVES,
  playerSliderMax,
  recommendedSpecForPlayers,
} from "../lib/game-player-recommend.ts";

test("every game family has a curve — no family silently falls through", () => {
  for (const f of GAME_FAMILIES) {
    assert.ok(GAME_PLAYER_CURVES[f], `missing curve for ${f}`);
  }
});

test("recommendations are non-negative and sane at 1 player", () => {
  for (const f of GAME_FAMILIES) {
    const r = recommendedSpecForPlayers(f, 1);
    assert.ok(r.cpuCores >= 1, `${f}: cpuCores`);
    assert.ok(r.ramMB >= 512, `${f}: ramMB`);
    assert.ok(r.diskGB >= 5, `${f}: diskGB`);
  }
});

test("more players never recommends less of any resource", () => {
  for (const f of GAME_FAMILIES) {
    const low = recommendedSpecForPlayers(f, 10);
    const high = recommendedSpecForPlayers(f, playerSliderMax(f));
    assert.ok(high.ramMB >= low.ramMB, `${f}: ram should not shrink with more players`);
    assert.ok(high.cpuCores >= low.cpuCores, `${f}: cpu should not shrink with more players`);
    assert.ok(high.diskGB >= low.diskGB, `${f}: disk should not shrink with more players`);
  }
});

test("minecraft's recommendation at its largest seeded tier (50 slots) is close to the real seeded spec", () => {
  // Real seeded tier: 8 GB / 3 vCPU / 50 GB disk for 50 slots (prisma/seed-gameplans.ts).
  // The fitted curve should land in the same ballpark, not wildly off.
  const r = recommendedSpecForPlayers("minecraft", 50);
  assert.ok(r.ramMB >= 6 * 1024 && r.ramMB <= 10 * 1024, `minecraft@50 ram out of range: ${r.ramMB}`);
  assert.ok(r.cpuCores >= 2 && r.cpuCores <= 4, `minecraft@50 cpu out of range: ${r.cpuCores}`);
});

test("playerSliderMax is at least 50 and scales with the family's largest seeded tier", () => {
  for (const f of GAME_FAMILIES) {
    assert.ok(playerSliderMax(f) >= 50, `${f}: slider max too small`);
  }
  // Rust's largest seeded tier is 150 slots — its slider should reach well past it.
  assert.ok(playerSliderMax("rust") >= 150);
});

